    "user_2": {"username": "bob", "email": "bob@corp.com", "role": "editor", "is_admin": False, "department": "marketing"},
    "user_3": {"username": "charlie", "email": "charlie@corp.com", "role": "admin", "is_admin": True, "department": "security"}
