def get_current_api_key():
    """Returns the currently valid API key hash - key is injected by sidecar"""
    import os
    key_file = os.environ.get("API_KEY_PATH", "/run/secrets/current_api_key")
    try:
        with open(key_file, "r") as f:
            return f.read().strip()
    except FileNotFoundError:
        return "dev-key-static-fallback-abc123"

async def verify_api_key(x_api_key: str = Header(...)):
    """Verify the provided API key against current valid key"""
    current_key = get_current_api_key()
    provided_hash = hashlib.sha256(x_api_key.encode()).hexdigest()
    expected_hash = hashlib.sha256(current_key.encode()).hexdigest()
    if provided_hash != expected_hash:
        raise HTTPException(status_code=401, detail="Invalid or expired API key")
    return x_api_key

class UserUpdate(BaseModel):
    username: Optional[str] = None
    email: Optional[str] = None
    role: Optional[str] = None
    is_admin: Optional[bool] = None
    department: Optional[str] = None

